// firebase.js
import { readFileSync } from "fs";
import { join } from "path";
import { homedir } from "os";
var firebaseConfig = {
  apiKey: "AIzaSyDfwsLRb8gPaWdxCXikZjJrM34N5426qrE",
  authDomain: "parrot-ai-9b46e.firebaseapp.com",
  projectId: "parrot-ai-9b46e",
  storageBucket: "parrot-ai-9b46e.firebasestorage.app",
  messagingSenderId: "311043780015",
  appId: "1:311043780015:web:d57792e91584bdf23d135a"
};
var CONFIG_PATH = join(homedir(), ".config", "parrot", "config.json");
function getUsername() {
  try {
    const raw = readFileSync(CONFIG_PATH, "utf8");
    const cfg = JSON.parse(raw);
    return cfg.username || null;
  } catch {
    return null;
  }
}
var app = initializeApp(firebaseConfig);
var db = getFirestore(app);
async function sendMessage(to, content) {
  const from = getUsername();
  if (!from) throw new Error("Parrot username not set. Run /parrot to set up.");
  await addDoc(collection(db, "messages"), {
    from,
    to,
    content,
    read: false,
    created_at: serverTimestamp()
  });
}
async function checkMessages() {
  const username2 = getUsername();
  if (!username2) throw new Error("Parrot username not set. Run /parrot to set up.");
  const q = query(
    collection(db, "messages"),
    where("to", "==", username2),
    where("read", "==", false)
  );
  const snapshot = await getDocs(q);
  const messages = [];
  const batch = writeBatch(db);
  snapshot.forEach((docSnap) => {
    const data = docSnap.data();
    messages.push({
      from: data.from,
      content: data.content,
      created_at: data.created_at?.toDate?.() ?? null
    });
    batch.update(doc(db, "messages", docSnap.id), { read: true });
  });
  if (messages.length > 0) await batch.commit();
  messages.sort((a, b) => (a.created_at ?? 0) - (b.created_at ?? 0));
  return messages;
}

// index.js
var username = getUsername();
var server = new McpServer({ name: "parrot", version: "0.1.0" });
server.tool(
  "send_message",
  `Send a Parrot message to another user. Their Claude will surface it at the start of their next session. You are currently "${username ?? "<not configured \u2014 run /parrot>"}".`,
  {
    to: external_exports.string().describe("Recipient's Parrot username"),
    content: external_exports.string().describe("The message to send")
  },
  async ({ to, content }) => {
    try {
      await sendMessage(to, content);
      return { content: [{ type: "text", text: `Sent to ${to}.` }] };
    } catch (err) {
      return { content: [{ type: "text", text: `Failed: ${err.message}` }] };
    }
  }
);
server.tool(
  "check_messages",
  `Check for unread Parrot messages addressed to "${username ?? "<not configured>"}". Returns messages and marks them read.`,
  {},
  async () => {
    try {
      const messages = await checkMessages();
      if (messages.length === 0) {
        return { content: [{ type: "text", text: "No unread messages." }] };
      }
      const text = messages.map(
        (m) => `From ${m.from}${m.created_at ? ` (${m.created_at.toISOString()})` : ""}:
${m.content}`
      ).join("\n\n---\n\n");
      return { content: [{ type: "text", text }] };
    } catch (err) {
      return { content: [{ type: "text", text: `Failed: ${err.message}` }] };
    }
  }
);
var transport = new StdioServerTransport();
await server.connect(transport);
